import{c as a,Q as t,j as r,m as o}from"./chunks/framework.g_l1frA7.js";const h=JSON.parse('{"title":"Rules","description":"","frontmatter":{},"headers":[],"relativePath":"automation/rules.md","filePath":"automation/rules.md","lastUpdated":null}'),n={name:"automation/rules.md"};function i(s,e,l,c,u,g){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h1><p>Pattern rules and treatment rules — the “always do this” layer for incoming transactions.</p><h2 id="types" tabindex="-1">Types <a class="header-anchor" href="#types" aria-label="Permalink to &quot;Types&quot;">​</a></h2><ul><li><strong>Pattern rules</strong> — <code>if merchant matches &quot;SQ *BLUE BOTTLE&quot; then category = Dining</code>. Stored under <code>repos/rules</code>, matched in <code>finsight-core::categorize</code>.</li><li><strong>Treatment rules</strong> — e.g. treat a payee as a transfer or a fee. Same engine, different effect.</li></ul><p>Each rule shows a match count and an enable toggle. Disabled rules are kept, not deleted, so you can experiment safely.</p><h2 id="creating-a-rule" tabindex="-1">Creating a rule <a class="header-anchor" href="#creating-a-rule" aria-label="Permalink to &quot;Creating a rule&quot;">​</a></h2><ol><li>Open <strong>Rules</strong> (or accept a Copilot-suggested rule from Insights).</li><li>Set the pattern (substring or normalized merchant), target category, and scope (any account vs specific).</li><li>Save — the rule runs on next categorization and on imports.</li></ol><p>Rules are ordered; earlier rules win. Reorder when two patterns overlap.</p><h2 id="agent-categorization-toggle" tabindex="-1">Agent categorization toggle <a class="header-anchor" href="#agent-categorization-toggle" aria-label="Permalink to &quot;Agent categorization toggle&quot;">​</a></h2><p><strong>Rules → Agent categorization</strong> controls whether LLM categorization runs at all. When off, incoming rows are left uncategorized for rules + deterministic keyword heuristics. See <a href="/FinSight/automation/categorization">Categorization</a>.</p><h2 id="proposals" tabindex="-1">Proposals <a class="header-anchor" href="#proposals" aria-label="Permalink to &quot;Proposals&quot;">​</a></h2><p>When the categorizer runs without a confident match, it may propose a rule. Review it in <strong>Rules → Proposals</strong> — accept, edit, or dismiss. A dismissed proposal will not recur for the same pattern.</p><p>See also: <a href="/FinSight/automation/categorization">Categorization</a>, <a href="/FinSight/guide/transactions">Transactions</a>.</p>',13)])])}const p=a(n,[["render",i]]);export{h as __pageData,p as default};
